#include <Arduino.h>
QueueHandle_t readings = nullptr;
void producer(void*) { int value = 0; for (;;) { ++value; if (xQueueSend(readings, &value, pdMS_TO_TICKS(100)) != pdPASS) vTaskDelay(pdMS_TO_TICKS(100)); vTaskDelay(pdMS_TO_TICKS(500)); } }
void setup() { Serial.begin(115200); readings = xQueueCreate(4, sizeof(int)); if (readings == nullptr || xTaskCreate(producer, "producer", 2048, nullptr, 1, nullptr) != pdPASS) { if (readings) vQueueDelete(readings); readings = nullptr; } }
void loop() { int value; if (readings && xQueueReceive(readings, &value, portMAX_DELAY) == pdPASS) Serial.println(value); else vTaskDelay(pdMS_TO_TICKS(100)); }

